#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.Vanilla.SeedPacks;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Level;

namespace MVZ2.GameContent.Buffs.Level
{
    [BuffDefinition(VanillaBuffNames.Level.commandBlockBlueprintCheck)]
    public class CommandBlockSeedPackCheckBuff : BuffDefinition
    {
        public CommandBlockSeedPackCheckBuff(string nsp, string name) : base(nsp, name)
        {
            AddAura(new SeedAura());
        }

        public class SeedAura : AuraEffectDefinition
        {
            public SeedAura() : base(VanillaBuffID.SeedPack.commandBlockBlueprint, 4)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var level = auraEffect.Source.GetLevel();
                foreach (var seed in level.GetAllSeedPacks())
                {
                    if (seed == null)
                        continue;
                    var seedDef = seed.Definition;
                    var isCommandBlock = seed.IsCommandBlock();
                    if (isCommandBlock == false)
                        continue;
                    if (seedDef == null)
                        continue;
                    if (seedDef.GetCost() <= 100)
                        continue;
                    results.Add(seed);
                }
            }
        }
    }
}
